// ponytail: fluxo agora e so e-mail. Monta a resposta a partir do evento realmente
// criado no Calendar (nao da saida do agente): funciona com pin data e nao depende
// de pairedItem. Se voltar o polling do Telegram, reintroduzir o ramo por origem.
const TG_TOKEN = '<TELEGRAM_BOT_TOKEN>';
const TG_CHAT_ID = '<TELEGRAM_CHAT_ID>';

const e = $input.item.json;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const dt = s => String(s ?? '').replace('T', ' ').slice(0, 16);

let text = `✅ <b>Evento criado!</b>\n\n<b>${esc(e.summary)}</b>\n\n\u{1F5D3} <b>Início:</b> ${dt(e.start?.dateTime || e.start?.date)}\n⏱ <b>Término:</b> ${dt(e.end?.dateTime || e.end?.date)}`;
if (e.location) text += `\n\n\u{1F4CD} <b>Local:</b> ${esc(e.location)}`;
if (e.description) text += `\n\n\u{1F4DD} ${esc(e.description)}`;
if (e.htmlLink) text += `\n\n<a href="${esc(e.htmlLink)}">Abrir no Google Calendar</a>`;

return { ...e, messageText: text, token: TG_TOKEN,
         tgBody: { chat_id: TG_CHAT_ID, parse_mode: 'HTML', text } };

// Normaliza o e-mail para o formato que o resto do fluxo espera.
const item = $input.item;
const j = item.json;

// Gmail Trigger (simple: false) devolve campos do mailparser no topo; "headers"
// vem como objeto e repete o nome do header dentro do valor ("Subject: ...").
const h = j.headers || {};
const unprefix = (v, name) => String(v ?? '').replace(new RegExp('^' + name + ':\\s*', 'i'), '').trim();
const subject = j.subject ?? unprefix(h.subject, 'Subject');
const from = j.from?.value?.[0]?.address ?? unprefix(h.from, 'From');
const body = j.text ?? j.snippet ?? '';

// ponytail: pega o primeiro anexo. Se um dia chegar e-mail com varios, escolher por tamanho/mime.
const bin = item.binary || {};
const key = Object.keys(bin)[0];

const MIME_BY_EXT = { jpg:'image/jpeg', jpeg:'image/jpeg', png:'image/png', gif:'image/gif',
                      webp:'image/webp', heic:'image/heic', pdf:'application/pdf' };
const IMAGES = ['image/jpeg','image/png','image/gif','image/webp','image/heic','image/heif'];

let kind = 'text';
if (key) {
  const b = bin[key];
  if (!b.mimeType || b.mimeType === 'application/octet-stream') {
    const ext = String(b.fileName || '').split('.').pop().toLowerCase();
    b.mimeType = MIME_BY_EXT[ext] || 'application/pdf';
  }
  item.binary = { data: b };            // os nos Gemini leem sempre o campo "data"
  kind = IMAGES.includes(b.mimeType) ? 'image' : 'document';
}

item.json = {
  source: 'email',
  kind,
  subject,
  from,
  fileName: key ? item.binary.data.fileName : null,
  // sem anexo: o AI Agent le daqui (mesmo campo que o Gemini preenche)
  content: kind === 'text' ? { subject, from, text: body } : undefined,
};
return item;
